//! Black-Scholes European call option price.
//!
//! Target law (risk-free rate r = 0, strike K = 1): `C = S * N(d1) - K * N(d2)`, where
//! `d1 = (ln(S/K) + w^2/2) / w`, `d2 = d1 - w`, `w = sigma * sqrt(t)` is the total volatility,
//! and `N` is the standard normal CDF. The two features are the spot `S in [0.6, 1.4]` and the
//! total volatility `w in [0.1, 0.5]`; the target is the call price `C in [0, 0.5]`.
//!
//! Data source: synthetic (generated by `phop_examples::black_scholes_dataset`).
//! Time budget (design §4.1): 90 s.
//!
//! Exact recovery of the Black-Scholes closed form (which contains the Gaussian CDF) is NOT
//! expected from today's engine; the demo shows the discoverer approximating the price surface.

use phop_core::Config;
use phop_examples::{black_scholes_dataset, report};

fn main() {
    let ds = black_scholes_dataset();
    // 90 s budget: the hardest demo (2 features, transcendental target), deepest search here.
    let cfg = Config::default().max_depth(4).max_epochs(1000).top_k(5);
    report(
        "Black-Scholes call price (synthetic, r=0, K=1)",
        "C = S * N(d1) - N(d2)   [feature 0 = S, feature 1 = w = sigma*sqrt(t)]",
        &ds,
        cfg,
    );
}
